# -*- coding: utf-8 -*-
"""11/12(木) 17:5x 「レインガードみたいに急激に売れなくなるの謎。パイが狭すぎた？」
クリアビューレインガードフィルムの日別（Meta fresh・17:5x取得）と、届いた人数・見せた回数・年齢の配分・天気（気象庁の日別降水量）を並べる。
数字は下に直接書いてある（取得した結果の転記）。転記の検算: 日別の広告費の合計 105,683円 = 期間まとめのクエリの広告費 105,683円。"""
import math
# date: cost, imp, reach, clicks, LPV, ATC, IC, purchase（元の広告セット。11/12は17:5x時点）
M = {'11-05': (1144, 260, 254, 12, 7, 0, 0, 0), '11-06': (11131, 2945, 2585, 139, 130, 15, 10, 6), '11-07': (11043, 2953, 2675, 133, 131, 21, 15, 8), '11-08': (20496, 5812, 5315, 265, 244, 45, 32, 19),
     '11-09': (20499, 4967, 4420, 214, 194, 29, 14, 7), '11-10': (18491, 3778, 3332, 132, 123, 21, 16, 8), '11-11': (17168, 3320, 3038, 113, 105, 8, 7, 3), '11-12': (5711, 1162, 1131, 45, 41, 0, 0, 0)}
COPY_1112 = (1414, 401, 383, 23, 18, 0, 0, 0)
assert sum(v[0] for v in M.values()) == 105683
LIFE = {'クリアビューレインガードフィルム': (105683, 25197, 18345, 1.3735), 'ワイド水切りワイパー': (169142, 50169, 35726, 1.4043), '伸縮ワックス洗車ブラシ': (140868, 31851, 23989, 1.3277), 'マグネットドアクッション': (86285, 24551, 16991, 1.4449)}  # 11/5〜11/12: cost, imp, reach, frequency
RAIN = {'11-04': (24.5, None, 0.0, 2.0), '11-05': (28.5, 4.5, 4.0, 27.5), '11-06': (None, 0.0, 2.0, 0.0), '11-07': (0.0, None, None, None), '11-08': (None, None, None, None), '11-09': (11.5, 0.0, 0.0, 2.5), '11-10': (6.0, 3.5, 0.0, 3.0), '11-11': (None, None, None, None)}  # 東京・大阪・名古屋・福岡の降水量mm（Noneは降水なし）
AGE = {'11-06': (1644, 4371, 4478), '11-07': (1510, 5068, 4031), '11-08': (3456, 8203, 7479), '11-09': (3044, 9142, 7559), '11-10': (2735, 7964, 6813), '11-11': (2830, 6983, 6182)}  # 45-54, 55-64, 65+ の広告費
print('日付: 広告費／CPM／CTR%／カート÷クリック%／購入÷クリック%／購入1件の広告費／購入｜55歳以上の割合｜東京の雨mm')
for d, (c, i, r, k, lp, atc, ic, pu) in M.items():
    a = AGE.get(d); rn = RAIN.get(d)
    print(f"  {d}: {c:,}／{c/i*1000:,.0f}／{k/i*100:.2f}／{atc/k*100:.1f}／{pu/k*100:.1f}／{'—' if not pu else f'{c/pu:,.0f}'}／{pu}件｜{'—' if not a else f'{(a[1]+a[2])/c*100:.0f}%'}｜{'—' if not rn else ('なし' if rn[0] is None else rn[0])}")
print(f"\n届いた人数（11/5〜11/12）: " + '・'.join(f"{n} {v[2]:,}人・1人あたり{v[3]:.2f}回" for n, v in LIFE.items()))
dr = sum(v[2] for v in M.values()); print(f"レインガード: 日ごとの届いた人数の合計 {dr:,}・期間の実人数 18,345 ＝ 毎日届いた人の約{18345/dr*100:.0f}%は初めて見る人")
k2 = M['11-11'][3] + M['11-12'][3] + COPY_1112[3]; p2 = M['11-11'][7] + M['11-12'][7]
kb = sum(M[d][3] for d in ('11-06', '11-07', '11-08', '11-09', '11-10')); pb = sum(M[d][7] for d in ('11-06', '11-07', '11-08', '11-09', '11-10'))
rate = pb / kb; lam = k2 * rate; pr = sum(math.exp(-lam) * lam ** x / math.factorial(x) for x in range(p2 + 1))
print(f"11/6〜11/10: {kb}クリックで{pb}件（{rate*100:.1f}%）／11/11〜11/12: {k2}クリックで{p2}件。同じ率なら {lam:.1f}件のはず → {p2}件以下になる確率 {pr*100:.1f}%")
